// Petites scènes animées des rencontres (planche « Les scènes jouées sur la carte », validée par Fi le 16 octobre).
// Dessin seulement : aucune règle ici.
let T=0,C='#b8432e';
const cl=(v,a=0,b=1)=>Math.max(a,Math.min(b,v)),seg=(k,a,b)=>cl((k-a)/(b-a)),n=v=>(+v).toFixed(2),mv=(k,a,b,x0,x1)=>x0+(x1-x0)*seg(k,a,b);
const ease=p=>p<.5?2*p*p:1-Math.pow(-2*p+2,2)/2;
// ---------- petites pièces de décor (coordonnées « locales » : le sol est à y = 11) ----------
const wheel=(cx,cy,rx,ry=rx)=>`<ellipse cx="${n(cx)}" cy="${n(cy)}" rx="${n(rx)}" ry="${n(ry)}" fill="none" stroke="#1b1406" stroke-width="1.5"/>`;
function bike({col=C,back=5.4,front=5.4,load=0}={}){const by=11-back,fy=11-front;
 let s=wheel(-8,by,5.4,back)+wheel(8,fy,5.4,front)+`<path d="M-8 ${n(by)} L-3 -1 L6 -1 L8 ${n(fy)} M-3 -1 L0 5.6 L6 -1 M0 5.6 L-8 ${n(by)} M6 -1 L7 -5 L9.4 -5.3" fill="none" stroke="${col}" stroke-width="1.7" stroke-linejoin="round"/><rect x="-13.4" y="-1.6" width="6.2" height="6.2" rx="1.3" fill="#b8432e" stroke="#1b1406" stroke-width=".5"/><rect x="-12.8" y="-5.2" width="9" height="3.6" rx="1.8" fill="#5f8a6a" stroke="#1b1406" stroke-width=".5"/>`;
 for(let i=0;i<load;i++){const w=Math.sin(T*5+i)*i*.7;s+=`<rect x="${n(-13+w)}" y="${n(-9-i*4)}" width="9" height="4" rx="1.2" fill="${['#c98b3a','#6a8fb5','#8a5a8a','#d9a03a','#5f8a6a'][i%5]}" stroke="#1b1406" stroke-width=".5"/>`;}
 return s;}
function riding(x,{dir=1,y=0,rot=0,col=C,jersey=C,cape=false,sweat=false,lean=0,back,front,load=0,wave=false,swat=false}={}){
 const a=T*9,fx=n(2.4*Math.cos(a)),fy=n(5.6+2.4*Math.sin(a)),gx=n(-2.4*Math.cos(a)),gy=n(5.6-2.4*Math.sin(a));
 let arm=wave?`<path d="M${1+lean} -9 L${4+lean} -16" stroke="#d9a37f" stroke-width="1.5" stroke-linecap="round"/>`:swat?`<path d="M${1+lean} -9 L${n(5+Math.sin(T*16)*2)} -15" stroke="#d9a37f" stroke-width="1.5" stroke-linecap="round"/>`:`<path d="M${1+lean} -9 L6 -5" stroke="#d9a37f" stroke-width="1.5" stroke-linecap="round"/>`;
 return `<g transform="translate(${n(x)} ${n(y)}) scale(${dir} 1) rotate(${n(rot)} 0 11)">${bike({col,back,front,load})}<path d="M-2.6 -3.5 L${fx} ${fy} M-2.6 -3.5 L${gx} ${gy}" stroke="#26343c" stroke-width="2" stroke-linecap="round"/><path d="M-3 -3.5 L${2+lean} -10" stroke="${jersey}" stroke-width="3.4" stroke-linecap="round"/>${cape?`<path d="M-4 -3 L${1+lean} -11 L${4+lean} -9 L1 -1Z" fill="#3f7a5a" opacity=".9"/>`:''}${arm}<circle cx="${4+lean}" cy="-12.6" r="2.6" fill="#f2d1a8" stroke="#1b1406" stroke-width=".5"/><path d="M${1.3+lean} -12.8 A2.8 2.8 0 0 1 ${6.7+lean} -13 Z" fill="#f6e7c1"/>${sweat?drops(6+lean,-14):''}</g>`;}
const drops=(x,y)=>[0,1].map(i=>{const p=(T*1.4+i*.5)%1;return `<path d="M${n(x+i*2)} ${n(y+p*6)} q.8 1.4 0 2 q-.8 -.6 0 -2Z" fill="#7fc0e8" opacity="${n(1-p)}"/>`;}).join('');
const parked=(x,rot=-8,o={})=>`<g transform="translate(${n(x)} 0) rotate(${rot} -8 5.6)">${bike(o)}</g>`;
function person(x,{f=1,pose='stand',y=0,op=1,jersey=C,skin='#f2d1a8',hat=true,s=1}={}){let legs='M0 -3 L-2 10 M0 -3 L2 10',arm=`M0 -10 L${-1*f} -4`,dy=0,body='M0 -3 L0 -11',hy=-13.6,extra='';
 const w=Math.sin(T*10);
 if(pose==='walk')legs=`M0 -3 L${n(-2*w)} 10 M0 -3 L${n(2*w)} 10`;
 if(pose==='wave')arm=`M0 -10 L${n(4*f+w)} -16`;
 if(pose==='swat')arm=`M0 -10 L${n(5*f*Math.sin(T*14))} -15`;
 if(pose==='shrug')arm='M0 -10 L-5 -14 M0 -10 L5 -14';
 if(pose==='arms')arm='M0 -10 L-5 -17 M0 -10 L5 -17';
 if(pose==='map'){arm=`M0 -10 L${4*f} -9`;extra=`<rect x="${f>0?2:-8}" y="-12" width="6" height="5" fill="#f6e7c1" stroke="#1b1406" stroke-width=".4"/>`;}
 if(pose==='belly')arm=`M0 -10 L${2*f} -5`;
 if(pose==='cup'){arm=`M0 -10 L${4*f} -9`;extra=`<rect x="${n(4*f-1)}" y="-11" width="2.4" height="3" fill="#f6e7c1" stroke="#1b1406" stroke-width=".3"/>`;}
 if(pose==='toast'){const p=(Math.sin(T*3)+1)/2;arm=`M0 -10 L${n((3+p*2)*f)} ${n(-12-p*3)}`;extra=`<rect x="${n((3+p*2)*f-.8)}" y="${n(-15-p*3)}" width="1.6" height="4" rx=".5" fill="#8a5a14"/>`;}
 if(pose==='dance'){const a=Math.sin(T*6);legs=`M0 -3 L${n(-2+a)} 10 M0 -3 L${n(2+a)} 10`;arm=`M0 -10 L${n(-5+a)} ${n(-15+a)} M0 -10 L${n(5+a)} ${n(-15-a)}`;dy=Math.abs(a)*-1;}
 if(pose==='sit'){dy=6;legs=`M0 -3 L${6*f} -2 L${7*f} 4`;arm=`M0 -9 L${5*f} -5`;}
 if(pose==='lie'){return `<g transform="translate(${n(x)} ${n(y)})" opacity="${n(op)}"><path d="M-8 9 L6 9" stroke="${jersey}" stroke-width="3.4" stroke-linecap="round"/><path d="M-8 9 L-14 10" stroke="#26343c" stroke-width="2" stroke-linecap="round"/><circle cx="9" cy="8.2" r="2.6" fill="${skin}" stroke="#1b1406" stroke-width=".5"/></g>`;}
 if(pose==='crouch'){dy=5;legs=`M0 -3 L${3*f} 1 L${1*f} 5`;arm=`M0 -9 L${5*f} -3`;}
 return `<g transform="translate(${n(x)} ${n(y+dy)}) scale(${s})" opacity="${n(op)}"><path d="${legs}" stroke="#26343c" stroke-width="2" stroke-linecap="round" fill="none"/><path d="${body}" stroke="${jersey}" stroke-width="3.4" stroke-linecap="round"/><path d="${arm}" stroke="#d9a37f" stroke-width="1.6" stroke-linecap="round" fill="none"/>${extra}<circle cx="0" cy="${hy}" r="2.6" fill="${skin}" stroke="#1b1406" stroke-width=".5"/>${hat?`<path d="M-2.7 -13.8 A2.8 2.8 0 0 1 2.7 -14 Z" fill="#f6e7c1" stroke="#1b1406" stroke-width=".5"/>`:''}</g>`;}
function tent(x,{p=1,col='#e0913a',glow=0,shake=0,w=10,frost=0,lean=0}={}){const h=11*p,dx=(shake?Math.sin(T*16)*.6:0)+lean;
 return `<path d="M${n(x-w)} 11 L${n(x+dx)} ${n(11-h)} L${n(x+w)} 11Z" fill="${col}" stroke="#1b1406" stroke-width=".6" stroke-linejoin="round"/><path d="M${n(x-3)} 11 L${n(x+dx*.6)} ${n(11-h*.62)} L${n(x+3)} 11Z" fill="${glow?'#ffd27a':'#5a3412'}"/>${frost?`<path d="M${n(x-w)} 11 L${n(x+dx)} ${n(11-h)} L${n(x+w)} 11Z" fill="#e8f4ff" opacity="${n(frost*.55)}"/>`:''}`;}
function fire(x,big=1){const h=(3+Math.sin(T*8)*.8+Math.sin(T*19)*.4)*big;
 return `<circle cx="${x}" cy="8" r="${9*big}" fill="#ffb347" opacity=".2"/><path d="M${x-3*big} 11 L${x+3*big} 9.6 M${x-3*big} 9.6 L${x+3*big} 11" stroke="#5b4228" stroke-width="1.2" stroke-linecap="round"/><path d="M${n(x-2*big)} 10 Q${n(x-2.2*big)} ${n(10-h*.6)} ${x} ${n(10-h)} Q${n(x+2.2*big)} ${n(10-h*.6)} ${n(x+2*big)} 10Z" fill="#f2a541"/><path d="M${n(x-big)} 10 Q${n(x-big)} ${n(10-h*.4)} ${x} ${n(10-h*.7)} Q${n(x+big)} ${n(10-h*.4)} ${n(x+big)} 10Z" fill="#ffe08a"/>`;}
const tree=(x,s=1,bend=0)=>`<g transform="translate(${x} 11) scale(${s}) rotate(${n(bend)} 0 0)"><rect x="-1.2" y="-17" width="2.4" height="17" fill="#5b4228"/><circle cx="0" cy="-23" r="8" fill="#3f6b4a"/><circle cx="-5" cy="-18" r="5.5" fill="#4b7a55"/><circle cx="5" cy="-19" r="5.5" fill="#355c40"/></g>`;
const bubble=(x,y,txt,col='#fffaf0')=>{const w=txt.length*2+5;return `<g transform="translate(${n(x)} ${n(y)}) scale(1.25)"><rect x="${n(-w/2)}" y="-5.4" width="${n(w)}" height="7.4" rx="2.4" fill="${col}" stroke="#1b1406" stroke-width=".4"/><path d="M-1 2 L0 4.4 L1.6 2Z" fill="${col}"/><text y=".3" text-anchor="middle" font-size="3.8" font-weight="800" fill="#1b3b38" font-family="Barlow, sans-serif">${txt}</text></g>`;};
const word=(x,y,txt,op=1,size0=4.4,col='#fffaf0',size=size0*1.35)=>`<text x="${n(x)}" y="${n(y)}" text-anchor="middle" font-size="${size}" font-weight="900" fill="${col}" stroke="#1b1406" stroke-width=".35" paint-order="stroke" opacity="${n(op)}" font-family="Barlow, sans-serif">${txt}</text>`;
const heart=(x,y,s=1,op=1)=>`<path transform="translate(${n(x)} ${n(y)}) scale(${s})" d="M0 3 C-4 0 -3.6 -3.6 -1.3 -3.3 C-.5 -3.1 0 -2.5 0 -2 C0 -2.5 .5 -3.1 1.3 -3.3 C3.6 -3.6 4 0 0 3Z" fill="#e0574a" opacity="${n(op)}"/>`;
const hearts=(x,y)=>[0,1,2].map(i=>{const p=(T*.7+i/3)%1;return heart(x+Math.sin(i*2+p*5)*3,y-p*12,.8,1-p);}).join('');
const dog=(x,{dir=1,run=false,lie=false,col='#8a5a2c'}={})=>{const l=run?Math.sin(T*18)*2:0;if(lie)return `<g transform="translate(${n(x)} 0) scale(${dir} 1)"><ellipse cx="0" cy="9" rx="5" ry="2.2" fill="${col}"/><circle cx="5" cy="8" r="2" fill="${col}"/><path d="M-5 9 q-3 ${n(-2+Math.sin(T*6)*2)} -4 -3" stroke="${col}" stroke-width="1" fill="none"/></g>`;
 return `<g transform="translate(${n(x)} ${run?n(-Math.abs(Math.sin(T*9))*1.2):0}) scale(${dir} 1)"><path d="M-4 6 L${n(-5+l)} 11 M-2 6 L${n(-1-l)} 11 M3 6 L${n(2+l)} 11 M5 6 L${n(6-l)} 11" stroke="#3a2a1c" stroke-width="1"/><ellipse cx="0" cy="5" rx="6" ry="2.8" fill="${col}"/><circle cx="6.5" cy="2.5" r="2.4" fill="${col}"/><path d="M5.6 1 L5 -1.2 L7 .4Z" fill="#3a2a1c"/><path d="M-6 4 q-3 -1 -3 -4" stroke="${col}" stroke-width="1" fill="none"/><circle cx="7.4" cy="2" r=".4" fill="#1b1406"/></g>`;};
const van=(x,{dir=1,col='#e9d7a6'}={})=>`<g transform="translate(${n(x)} 0) scale(${dir} 1)"><rect x="-16" y="-9" width="30" height="16" rx="3" fill="${col}" stroke="#1b1406" stroke-width=".6"/><path d="M8 -9 L14 -9 L18 -2 L18 7 L8 7Z" fill="${col}" stroke="#1b1406" stroke-width=".6"/><path d="M10 -7 L13.6 -7 L16.4 -2 L10 -2Z" fill="#9cc6dc"/><rect x="-12" y="-6" width="8" height="5" rx="1" fill="#9cc6dc"/><rect x="-2" y="-6" width="8" height="5" rx="1" fill="#9cc6dc"/>${wheel(-9,8,3.2)}${wheel(11,8,3.2)}</g>`;
const kid=(x,c)=>person(x,{pose:'wave',jersey:c,s:.7,hat:false,y:3.4});
const bench=(x)=>`<rect x="${x-7}" y="4" width="14" height="1.6" fill="#7a5a34"/><rect x="${x-6}" y="5.6" width="1.2" height="5.4" fill="#5b4228"/><rect x="${x+5}" y="5.6" width="1.2" height="5.4" fill="#5b4228"/>`;
const sign=(x,txt,col='#f6e7c1')=>{const w=txt.length*2.1+5;return `<rect x="${x-.6}" y="-14" width="1.2" height="25" fill="#5b4228"/><rect x="${n(x-w/2)}" y="-19" width="${n(w)}" height="7" rx="1.2" fill="${col}" stroke="#1b3b38" stroke-width=".5"/><text x="${x}" y="-14.2" text-anchor="middle" font-size="3.6" font-weight="800" fill="#1b3b38" font-family="Barlow, sans-serif">${txt}</text>`;};
const water=(y0=11,h=6)=>`<rect x="-80" y="${y0}" width="160" height="${h}" fill="#4f8fb8"/>`+[0,1,2,3,4].map(i=>{const x=((T*8+i*34)%160)-80;return `<path d="M${n(x)} ${y0+2} q2 -1 4 0" stroke="#bfe0f2" stroke-width=".5" fill="none"/>`;}).join('');
const spray=(x,y,dir=-1)=>[0,1,2,3,4,5].map(i=>{const p=(T*2.2+i/6)%1;return `<circle cx="${n(x+dir*p*12+Math.sin(i)*2)}" cy="${n(y-Math.sin(p*Math.PI)*6)}" r=".7" fill="#8b8270" opacity="${n(1-p)}"/>`;}).join('');
const stars=op=>[[20,15],[60,30],[95,12],[140,25],[180,10],[220,28],[260,14],[300,30],[120,45],[240,48]].map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="${i%3?1:1.5}" fill="#fffbe8" opacity="${n(op*(.6+.4*Math.sin(T*2+i)))}"/>`).join('');
const rain=(dens=40,col='#cfe3f1')=>`<g stroke="${col}" stroke-width="1" opacity=".6">`+Array.from({length:dens},(_,i)=>{const x=(i*37.7)%440-58,y=((T*300+i*53)%190)-20;return `<path d="M${n(x)} ${n(y)} l-3 9"/>`;}).join('')+`</g>`;
const wind=()=>`<g stroke="#f6f6ee" stroke-width="1.2" stroke-linecap="round" opacity=".8" fill="none">`+[0,1,2,3,4].map(i=>{const x=380-((T*160+i*70)%480),y=40+i*16;return `<path d="M${n(x)} ${y} h18 q4 0 4 -3"/>`;}).join('')+`</g>`;
const clouds=(col='#55606a')=>`<g fill="${col}"><ellipse cx="80" cy="22" rx="60" ry="16"/><ellipse cx="210" cy="16" rx="80" ry="18"/><ellipse cx="300" cy="26" rx="50" ry="13"/></g>`;
// Cadre : la vraie carte du jeu autour de la case du cycliste (viewBox -48 0 416 150, la case au centre).
const MAP_W=1261,MAP_H=842,SPAN=90;
function frame(uid,sc,o){const night=sc.sky==='night',dusk=sc.sky==='dusk',s0=320/SPAN;
 let s=`<defs><radialGradient id="v${uid}" cx="50%" cy="72%" r="62%"><stop offset=".35" stop-color="#0b1630" stop-opacity="0"/><stop offset="1" stop-color="#0b1630" stop-opacity="${night?.85:dusk?.45:.18}"/></radialGradient></defs>`;
 s+=`<rect x="-48" width="416" height="150" fill="#7f9a62"/>`;
 if(o.href&&Number.isFinite(o.x))s+=`<image href="${o.href}" x="${n(160-o.x*s0)}" y="${n(117-o.y*s0)}" width="${n(MAP_W*s0)}" height="${n(MAP_H*s0)}" preserveAspectRatio="none"/>`;
 const tint={night:['#0d1834',.5],dusk:['#e9874b',.22],storm:['#28323c',.45],rain:['#5d6b78',.3],hot:['#ffb347',.25],day:['#000',0]}[sc.sky||'day'];
 if(tint[1])s+=`<rect x="-48" width="416" height="150" fill="${tint[0]}" opacity="${tint[1]}"/>`;
 if(night)s+=stars(.8);
 s+=`<path d="M160 78 l34 19.6 v39.2 l-34 19.6 l-34 -19.6 v-39.2Z" fill="#f2a541" fill-opacity=".10" stroke="#f2a541" stroke-width="2" stroke-dasharray="5 4" opacity=".85"/>`;
 if(sc.road)s+=`<path d="M-60 140 C80 128 220 146 380 134" stroke="#d9c89c" stroke-width="7" fill="none" opacity=".8" stroke-linecap="round"/>`;
 if(sc.pre)s+=`<g opacity=".92">${sc.pre}</g>`;
 s+=`<ellipse cx="160" cy="139" rx="70" ry="7" fill="#1b1406" opacity=".12"/>`;
 s+=`<g transform="translate(160 112) scale(2.4)">${sc.body||''}</g>`;
 if(sc.over)s+=sc.over;
 s+=`<rect x="-48" width="416" height="150" fill="url(#v${uid})"/>`;
 if(sc.light)s+=`<g transform="translate(160 112) scale(2.4)">${sc.light}</g>`;
 return s;}
// ---------- les 51 scènes ----------
const BY_TITLE={};
const add=(g,title,txt,P,fn,tag='')=>{BY_TITLE[title]={g,title,P,fn};};
// 1 · Galères en route
add('galeres','Le rayon qui casse','« Tic ! » une étincelle sur la roue arrière, la roue se voile et se dandine.',5,k=>{const x=mv(k,0,1.6,-60,-6),b=k>1.6;return {road:1,body:riding(x,{back:b?5.4+Math.sin(T*14)*1.1:5.4,rot:b?Math.sin(T*14)*1.2:0})+(k>1.6&&k<2.1?`<path d="M${n(x-10)} 0 l2 3 l3 -1 l-2 3 l3 2 l-4 0 l-1 3 l-1 -3 l-4 0 l3 -2 l-2 -3 l3 1Z" fill="#ffe08a"/>`:'')+(b?word(x-8,-6,'tic !',seg(k,1.6,2)):'')};},'Mécanique');
add('galeres','Pschhh…','Le pneu arrière se dégonfle d’un coup, le vélo s’affaisse : « pschhh ».',5,k=>{const x=mv(k,0,1.8,-60,-6),p=seg(k,1.8,2.8),bk=5.4-p*2.2;return {road:1,body:riding(x,{back:bk,rot:-p*4})+(p>0&&p<1?[0,1,2].map(i=>`<path d="M${n(x-14-i*2-p*6)} ${n(7-i*2)} h-3" stroke="#f6f6ee" stroke-width=".7"/>`).join(''):'')+(k>1.8?word(x-6,-20,'pschhh…',1-seg(k,3.6,4.6),4):'')};},'Mécanique');
add('galeres','Le dérailleur capricieux','La chaîne saute, petites étincelles au pédalier, un engrenage tourne de travers : « clac ! ».',4,k=>{const x=mv(k,0,1.4,-50,-6),g=Math.floor(T*3)%2;return {road:1,body:riding(x)+(k>1.4?`<g transform="translate(${n(x+12)} -24) rotate(${n(Math.floor(T*4)*35)})"><circle r="4" fill="#b9c1c4" stroke="#1b1406" stroke-width=".5"/>${[0,60,120,180,240,300].map(a=>`<rect x="-.9" y="-5.8" width="1.8" height="2.4" fill="#b9c1c4" stroke="#1b1406" stroke-width=".4" transform="rotate(${a})"/>`).join('')}<circle r="1.4" fill="#1b1406"/></g>`+(g?`<circle cx="${n(x)}" cy="5.6" r="2.2" fill="#ffe08a" opacity=".9"/>`:'')+word(x+12,-31,'clac !',g?1:.3,3.6):'')};},'Mécanique');
add('galeres','Les chiens de la ferme','Un chien sort de la ferme et court en aboyant derrière le cycliste, qui accélère.',4.5,k=>{const x=mv(k,0,4.5,-70,80);return {road:1,body:`<rect x="-62" y="-6" width="16" height="17" fill="#d9c4a0" stroke="#1b1406" stroke-width=".5"/><path d="M-64 -6 L-54 -13 L-44 -6Z" fill="#8f3b26"/>`+riding(x,{sweat:true,lean:1})+dog(x-24+Math.sin(T*3)*2,{run:true})+word(x-20,-6,'ouaf !',(Math.sin(T*8)+1)/2,3.8)+[0,1,2].map(i=>`<path d="M${n(x-16-i*3)} ${-6+i*4} h-6" stroke="#f6f6ee" stroke-width=".6"/>`).join('')};},'Route');
add('galeres','Trop de bagages','Une pile de sacs tangue sur le porte-bagages, il avance au ralenti en suant.',5,k=>{const x=mv(k,0,5,-60,30);return {road:1,body:riding(x,{load:5,sweat:true,rot:Math.sin(T*3)*1.5})};},'Route');
add('galeres','La guêpe','Une guêpe tourne autour de la tête, il agite la main pour la chasser.',4,k=>{const x=mv(k,0,4,-40,20),wx=x+5+7*Math.cos(T*6),wy=-15+4*Math.sin(T*9);return {road:1,body:riding(x,{swat:true})+`<g transform="translate(${n(wx)} ${n(wy)})"><ellipse rx="1.6" ry="1" fill="#f2c14e" stroke="#1b1406" stroke-width=".3"/><path d="M-.4 -1 v2 M.5 -1 v2" stroke="#1b1406" stroke-width=".4"/><ellipse cx="0" cy="-1.4" rx="1" ry=".6" fill="#e8f4ff" opacity="${n(.5+.5*Math.sin(T*60))}"/></g>`+word(x+12,-24,'bzz',.8,3)};},'Route');
add('galeres','Route barrée','Une barrière rouge et blanche, panneau « Déviation » : il s’arrête et fait demi-tour.',5,k=>{const back=k>3,x=back?mv(k,3,5,-4,-70):mv(k,0,1.8,-60,-4);return {road:1,body:`<rect x="16" y="2" width="1.2" height="9" fill="#26343c"/><rect x="34" y="2" width="1.2" height="9" fill="#26343c"/><rect x="14" y="0" width="24" height="3" fill="#f6f6ee" stroke="#b8432e" stroke-width="1" stroke-dasharray="3 3"/>`+sign(26,'DÉVIATION ↩','#f2c14e')+riding(x,{dir:back?-1:1})+(k>1.8&&k<3?bubble(x+4,-21,'zut'):'')};},'Route');
add('galeres','Où est passé le chemin ?','Le chemin s’efface dans l’herbe, il sort la carte et regarde partout : « ? ».',5,k=>{return {pre:`<rect y="133" width="${n(320-seg(k,0,2)*170)}" height="6" fill="#bfb39a" opacity=".8"/>`,body:parked(-20)+person(-2,{pose:'map',f:Math.floor(T*1.2)%2?1:-1})+[0,1,2].map(i=>{const p=(T*.8+i/3)%1;return word(-2+(i-1)*6,-20-p*10,'?',1-p,5);}).join('')};},'Route');
add('galeres','Le changement d’heure','Une horloge s’affole, le ciel passe du jour au soir en quelques secondes.',5,k=>{const p=seg(k,.5,4);return {pre:`<rect x="-48" width="416" height="150" fill="#e9a86b" opacity="${n(p*.8)}"/>`,road:1,body:riding(mv(k,0,5,-50,40)),over:`<g transform="translate(270 34)"><circle r="16" fill="#f6e7c1" stroke="#1b3b38" stroke-width="2"/><path d="M0 0 L0 -11" stroke="#1b3b38" stroke-width="2" transform="rotate(${n(T*720)})"/><path d="M0 0 L7 0" stroke="#b8432e" stroke-width="2.4" transform="rotate(${n(T*60)})"/></g>`};},'Route');
add('galeres','39 °C sans ombre','Un soleil énorme qui pulse, l’air qui ondule, le thermomètre qui monte, le cycliste qui transpire.',5,k=>{const s=1+Math.sin(T*3)*.06;return {sky:'hot',road:1,pre:`<g transform="translate(250 34) scale(${n(s)})"><circle r="20" fill="#ffd34d"/>${Array.from({length:10},(_,i)=>`<path d="M0 -26 L0 -33" stroke="#ffd34d" stroke-width="3" transform="rotate(${i*36+T*20})"/>`).join('')}</g>`,body:riding(mv(k,0,5,-55,20),{sweat:true})+[0,1,2].map(i=>`<path d="M${-40+i*30} ${n(-4-Math.sin(T*3+i)*2)} q3 -2 6 0 t6 0" stroke="#fff6d8" stroke-width=".6" fill="none" opacity=".7"/>`).join(''),over:`<g transform="translate(26 30)"><rect x="-3" y="0" width="6" height="34" rx="3" fill="#f6e7c1" stroke="#1b3b38"/><rect x="-1.4" y="${n(30-seg(k,0,3)*26)}" width="2.8" height="${n(seg(k,0,3)*26+3)}" fill="#e0574a"/><text x="8" y="12" font-size="12" font-weight="900" fill="#b8432e" font-family="Barlow">39°</text></g>`};},'Météo');
add('galeres','L’orage sur le col','Nuages noirs, un éclair qui illumine tout, la pluie ; il grimpe sous la cape.',5,k=>{const fl=(k>2&&k<2.25)||(k>3.6&&k<3.75);return {sky:'storm',peaks:'M0 100 L60 70 L120 40 L160 30 L200 45 L260 75 L320 90 L320 150 L0 150Z',pre:clouds('#2c343c'),body:riding(mv(k,0,5,-40,10),{cape:true,lean:1}),over:rain(40)+(fl?`<rect x="-48" width="416" height="150" fill="#fff" opacity=".55"/><path d="M200 10 L188 48 L198 48 L184 86" stroke="#fff8c4" stroke-width="3" fill="none"/>`:'')};},'Météo');
add('galeres','La drache','Une pluie battante, des éclaboussures dans les flaques, il roule sous la cape.',4,k=>{return {sky:'rain',road:1,pre:clouds('#6b757e'),body:riding(mv(k,0,4,-60,40),{cape:true})+[-30,0,30].map((x,i)=>{const p=(T*1.6+i*.3)%1;return `<ellipse cx="${x}" cy="12" rx="${n(1+p*5)}" ry="${n(.4+p*1.2)}" fill="none" stroke="#cfe3f1" stroke-width=".5" opacity="${n(1-p)}"/>`;}).join(''),over:rain(70)};},'Météo');
add('galeres','Vent de face','Le vent souffle de face : il se penche, avance au ralenti, l’arbre plie, une feuille s’envole.',5,k=>{const lf=(T*.9)%1;return {road:1,body:tree(40,1,-6+Math.sin(T*4)*3)+riding(mv(k,0,5,-55,-5),{lean:1.5,sweat:true})+`<ellipse cx="${n(50-lf*110)}" cy="${n(-20+Math.sin(lf*12)*4)}" rx="1.4" ry=".8" fill="#6f9a3a" transform="rotate(${n(T*300)} ${n(50-lf*110)} ${n(-20+Math.sin(lf*12)*4)})"/>`,over:wind()};},'Météo');
add('galeres','Les gravillons','Les graviers giclent, la roue arrière chasse, il rattrape de justesse.',4.5,k=>{const x=mv(k,0,1.6,-60,-4),sk=k>1.6&&k<3.2;return {road:1,pre:`<g fill="#9a907a">${Array.from({length:30},(_,i)=>`<circle cx="${130+i*3.5}" cy="${134+(i*7)%5}" r="1"/>`).join('')}</g>`,body:riding(sk?x+Math.sin(T*20)*1.2:x,{rot:sk?Math.sin(T*12)*7:0})+(sk?spray(x-8,10):'')+(k>2.4&&k<3.6?word(x,-22,'ouf…',1,3.8):'')};},'Inattention');
add('galeres','Le nid-de-poule','Un gros trou dans la route : la roue tombe dedans, le vélo saute, « aïe ! ».',4,k=>{const x=mv(k,0,4,-60,50),d=Math.abs(x-6),j=d<8?Math.sin((8-d)/8*Math.PI)*-4:0;return {road:1,body:`<ellipse cx="6" cy="11.6" rx="6" ry="1.6" fill="#3a3528"/>`+riding(x,{y:j,rot:j*1.5})+(x>6&&x<30?word(x-2,-24,'aïe !',1,4.2):'')};},'Inattention');
add('galeres','La mauvaise bifurcation','Il passe le panneau, file tout droit… « ? » et fait demi-tour.',5.5,k=>{const back=k>3,x=back?mv(k,3,5.5,55,-20):mv(k,0,2.4,-60,55);return {road:1,body:`<rect x="-0.6" y="-16" width="1.2" height="27" fill="#5b4228"/><path d="M0 -15 h12 l3 2.5 l-3 2.5 h-12Z" fill="#f6e7c1" stroke="#1b3b38" stroke-width=".5"/><path d="M0 -8 h-12 l-3 2.5 l3 2.5 h12Z" fill="#f6e7c1" stroke="#1b3b38" stroke-width=".5"/>`+riding(x,{dir:back?-1:1})+(k>2.4&&k<3.3?word(x,-22,'?',1,7):'')};},'Inattention');
add('galeres','Les affaires oubliées','Il repart… la sacoche est restée sur le banc ! « ! » et il revient la chercher.',5.5,k=>{const back=k>3,x=back?mv(k,3,5.2,50,-30):mv(k,.4,2.6,-30,50);return {road:1,body:bench(-40)+(k<5.2?`<rect x="-44" y="0.4" width="6.2" height="3.6" rx="1" fill="#b8432e" stroke="#1b1406" stroke-width=".5"/>`:'')+riding(x,{dir:back?-1:1})+(k>2.6&&k<3.4?word(x,-22,'!',1,8,'#ffe08a'):'')};},'Inattention');
add('galeres','La chute à l’arrêt','À l’arrêt, il n’arrive pas à poser le pied : il bascule tout doucement sur le côté. Des étoiles, puis il se relève.',5.5,k=>{const p=ease(seg(k,1,2.2)),up=k>3.6;return {road:1,body:up?parked(-6,80)+person(10,{pose:'shrug'}):riding(-6,{rot:p*80})+(p>=1?[0,1,2].map(i=>`<path transform="translate(${n(8+Math.cos(T*4+i*2)*5)} ${n(-2+Math.sin(T*4+i*2)*2)})" d="M0 -1.6 L.5 -.5 L1.6 -.4 L.8 .4 L1 1.6 L0 1 L-1 1.6 L-.8 .4 L-1.6 -.4 L-.5 -.5Z" fill="#ffe08a"/>`).join(''):'')};},'Inattention');
// 2 · Belles rencontres en route
add('belles','« On t’avance ? »','Une camionnette s’arrête, le vélo monte sur le toit, il saute à bord et la camionnette repart.',6,k=>{const vx=k<1.6?mv(k,0,1.6,110,12):k<3.6?12:mv(k,3.6,6,12,120),onRoof=k>2.6,bx=onRoof?vx:mv(k,1.8,2.6,-26,vx),by=onRoof?-20:mv(k,1.8,2.6,0,-20);return {road:1,body:van(vx,{dir:-1})+(k<3.2?person(-14,{pose:k<1.6?'wave':'stand'}):'')+`<g transform="translate(${n(bx-(-26))} ${n(by)})">${parked(-26,0)}</g>`+(k>1.4&&k<2.6?bubble(vx-6,-16,'On t’avance ?'):'')};});
add('belles','La rivière glacée','Il pose le vélo, saute dans la rivière : « plouf », des éclaboussures, puis « brrr ! ».',5.5,k=>{const inn=k>1.4&&k<4,py=inn?6:0;return {body:water(8,8)+tree(-50,.9)+parked(-36)+(k<1.4?person(mv(k,0,1.4,-26,-6),{pose:'walk',hat:false}):inn?person(-2+Math.sin(T*20)*.4,{y:py,hat:false,pose:'arms'}):person(-14,{hat:false,pose:'stand'}))+(k>1.4&&k<2?spray(-2,6,1)+spray(-2,6,-1):'')+(k>1.5&&k<2.2?word(-2,-18,'plouf',1,4):'')+(k>2.4&&k<4.6?word(4,-22,'brrr !',1,4,'#cfe3f1'):'')};});
add('belles','Une halte imprévue','Un banc à l’ombre d’un arbre, il s’assoit avec une boisson chaude qui fume. Un oiseau passe.',5,k=>{const b=(T*.25)%1;return {body:tree(-18,1.1)+bench(0)+parked(24,-6)+person(0,{pose:'sit',f:1,hat:false})+`<rect x="4.6" y="-1" width="2" height="2.6" fill="#f6e7c1"/>`+[0,1].map(i=>{const p=(T*.8+i*.5)%1;return `<path d="M${n(5.6+Math.sin(p*6)*.8)} ${n(-2-p*7)} q.6 -1 0 -2" stroke="#f6f6ee" stroke-width=".4" fill="none" opacity="${n(1-p)}"/>`;}).join('')+`<path d="M${n(-60+b*120)} ${n(-34+Math.sin(T*4))} q2 -1.6 4 0 q2 -1.6 4 0" stroke="#26343c" stroke-width=".6" fill="none"/>`};});
add('belles','Le cycliste du coin','Un cycliste du pays le rattrape, roule à côté de lui et lui fait signe : « par ici ! ».',5,k=>{const x=mv(k,0,5,-45,20),o=mv(k,0,2,-70,x+18);return {road:1,body:riding(o,{jersey:'#3a6fb0',col:'#3a6fb0',wave:k>2&&k<3.6})+riding(x)+(k>2.2&&k<3.8?bubble(o+4,-21,'par ici !'):'')};});
add('belles','Paysage exceptionnel','Il s’arrête au point de vue : des rayons dorés et des paillettes sur le panorama, « waouh ».',5,k=>{return {peaks:'M0 95 L40 60 L80 85 L120 35 L150 55 L190 25 L230 60 L280 40 L320 70 L320 150 L0 150Z',pre:`<g transform="translate(250 60)" opacity=".7">${Array.from({length:8},(_,i)=>`<path d="M0 0 L-8 -90 L8 -90Z" fill="#ffe7a0" transform="rotate(${n(i*45+T*8)})" opacity=".35"/>`).join('')}<circle r="14" fill="#ffd34d"/></g>`,body:parked(-40)+person(-24,{pose:'arms'})+[0,1,2,3,4].map(i=>{const p=(T*.6+i/5)%1;return `<path transform="translate(${-10+i*14} ${n(-30+Math.sin(i*3)*8)}) scale(${n(Math.sin(p*Math.PI))})" d="M0 -2 L.6 -.6 L2 0 L.6 .6 L0 2 L-.6 .6 L-2 0 L-.6 -.6Z" fill="#fff4c4"/>`;}).join('')+(k>1.2?word(-24,-22,'waouh',seg(k,1.2,1.8),4):'')};});
add('belles','La voie verte','Une belle voie sans voitures : les arbres défilent, il roule tranquille, des papillons.',4,k=>{const off=(T*30)%40;return {road:1,body:[0,1,2,3,4].map(i=>tree(-80+i*40-off+20,.8)).join('')+riding(0)+`<g transform="translate(${n(14+Math.sin(T*2)*6)} ${n(-14+Math.cos(T*3)*3)})"><path d="M0 0 l-2 -1.6 l0 3.2Z M0 0 l2 -1.6 l0 3.2Z" fill="#f2a541" transform="scale(1 ${n(.4+.6*Math.abs(Math.sin(T*14)))})"/></g>`};});
add('belles','Le petit bac','Un petit bac à câble traverse la rivière avec le vélo et le cycliste à bord.',5.5,k=>{const x=mv(k,.3,5,-58,40);return {body:`<path d="M-80 -6 L80 -6" stroke="#5b4228" stroke-width=".5"/>`+water(6,10)+`<g transform="translate(${n(x)} ${n(Math.sin(T*2)*.4)})"><rect x="-14" y="5" width="28" height="3.4" fill="#8a6a3a" stroke="#1b1406" stroke-width=".4"/><path d="M0 5 L0 -6" stroke="#5b4228" stroke-width=".5"/><g transform="translate(-4 -6) scale(.9)">${parked(0,0)}</g>${person(9,{y:-6,pose:'wave'})}</g>`};});
add('belles','Les gorges','Une route au bord des gorges, la rivière tout en bas ; il crie « ho ! » et l’écho répond.',5,k=>{const e=k%2.5;return {mtn:false,pre:`<path d="M-48 0 L70 0 L60 60 L80 150 L-48 150Z M368 0 L250 0 L265 70 L240 150 L368 150Z" fill="#a06a44"/><path d="M60 140 Q160 120 260 140 L260 150 L60 150Z" fill="#4f8fb8"/>`,body:riding(mv(k,0,5,-40,30))+word(-10,-24,'ho !',1-seg(e,.4,1),4)+word(30,-30,'ho…',seg(e,.8,1)*(1-seg(e,1.4,2)),3.2)+word(48,-36,'ho…',seg(e,1.4,1.6)*(1-seg(e,2,2.4)),2.6)};});
add('belles','L’addition','Assis en terrasse, le patron arrive avec l’addition… et la déchire : « c’est offert ! ».',5.5,k=>{const wx=mv(k,.5,2,60,14);return {body:`<rect x="-14" y="-2" width="16" height="1.4" fill="#7a5a34"/><rect x="-6.8" y="-.6" width="1.4" height="11.6" fill="#5b4228"/><path d="M-6 -30 L-6 -2 M-20 -24 Q-6 -34 8 -24Z" stroke="#5b4228" stroke-width=".8" fill="#e0574a"/>`+person(-16,{pose:'sit',f:1,hat:false})+person(wx,{f:-1,jersey:'#f6f6ee',hat:false,pose:k<2?'walk':'stand'})+(k>2.2&&k<3.4?`<rect x="${n(wx-6)}" y="-12" width="4" height="5" fill="#fffaf0" stroke="#1b1406" stroke-width=".3"/>`:'')+(k>3.4?[0,1].map(i=>`<rect x="${n(wx-6+i*2.4+seg(k,3.4,4.4)*(i?3:-3))}" y="${n(-12+seg(k,3.4,4.4)*18)}" width="2" height="5" fill="#fffaf0" transform="rotate(${i?30:-30} ${n(wx-5)} -10)"/>`).join(''):'')+(k>3.4?bubble(wx,-21,'c’est offert !')+hearts(-16,-14):'')};});
add('belles','Le marché','Des étals colorés : la marchande lui lance une pomme, il l’attrape au vol.',5,k=>{const p=seg(k,1.6,2.6);const stall=(x,c)=>`<rect x="${x-10}" y="0" width="20" height="11" fill="#c9a36b" stroke="#1b1406" stroke-width=".4"/><path d="M${x-12} -8 h24 l-2 6 h-20Z" fill="${c}"/><path d="M${x-12} -8 h24" stroke="#fff" stroke-width="1.2" stroke-dasharray="3 3"/>${[0,1,2,3].map(i=>`<circle cx="${x-6+i*4}" cy="-1" r="1.6" fill="${['#e0574a','#f2a541','#6f9a3a','#e0574a'][i]}"/>`).join('')}`;
 return {body:stall(-34,'#e0574a')+stall(20,'#3a6fb0')+person(20,{f:-1,jersey:'#6b4a8a',hat:false,pose:k>1.4&&k<1.8?'wave':'stand'})+person(-6,{pose:k>2.4?'cup':'stand'})+(p>0&&p<1?`<circle cx="${n(18-p*22)}" cy="${n(-12-Math.sin(p*Math.PI)*10)}" r="1.6" fill="#e0574a"/>`:'')+(k>2.6?hearts(-6,-18):'')};});
add('belles','« Hello ! »','Des enfants au bord de la route lui font de grands signes, il répond, des petits cœurs.',4.5,k=>{const x=mv(k,0,4.5,-60,50);return {road:1,body:kid(10,'#e0574a')+kid(17,'#3a6fb0')+kid(24,'#6f9a3a')+riding(x,{wave:Math.abs(x-17)<20})+(Math.abs(x-17)<24?hearts(17,-14)+word(17,-20,'Hello !',1,3.6):'')};});
add('belles','D’autres voyageurs à vélo','Deux vélos chargés arrivent en face, ils s’arrêtent et se saluent : « Hello ! », bises de cyclos.',5,k=>{const x=mv(k,0,2,-60,-12),o=mv(k,0,2,70,14);return {road:1,body:riding(x,{wave:k>2})+riding(o,{dir:-1,jersey:'#3a6fb0',col:'#3a6fb0',load:2,wave:k>2})+riding(o+18,{dir:-1,jersey:'#6f9a3a',col:'#6f9a3a',load:2})+(k>2.1?bubble(1,-24,'Hello !')+hearts(1,-30):'')};});
// 3 · Mauvaises soirées
add('soirg','Les moustiques','Une nuée de moustiques tourne autour de lui devant la tente, il gesticule.',4,k=>{return {sky:'dusk',body:tent(10)+parked(-34)+person(-12,{pose:'swat',hat:false})+Array.from({length:12},(_,i)=>`<circle cx="${n(-12+Math.cos(T*(3+i%4)+i)*(5+i%3*2))}" cy="${n(-10+Math.sin(T*(4+i%3)+i*2)*5)}" r=".5" fill="#1b1406"/>`).join('')+word(-12,-24,'bzzz',1,3)};});
add('soirg','C’était quoi ce bruit ?','La nuit, deux yeux brillent dans le buisson, la lampe frontale balaie : « ?! ».',5,k=>{const blink=Math.floor(T*2)%5===0,a=Math.sin(T*1.4)*20;return {sky:'night',body:tent(4,{glow:1})+parked(-30)+`<ellipse cx="38" cy="7" rx="12" ry="6" fill="#26402c"/>`+(blink?'':`<circle cx="36" cy="5" r=".8" fill="#ffe08a"/><circle cx="39" cy="5" r=".8" fill="#ffe08a"/>`)+word(4,-12,'?!',1,5),light:`<path d="M4 2 L46 ${n(-6+a)} L46 ${n(12+a)}Z" fill="#fff4c4" opacity=".22"/>`};});
add('soirg','La patrouille','Une voiture aux gyrophares bleus s’arrête près de la tente, la lampe se braque : « Bonsoir… ».',5,k=>{const vx=mv(k,0,1.8,90,36),b=Math.floor(T*4)%2;return {sky:'night',body:tent(-14,{glow:1})+parked(-40)+van(vx,{dir:-1,col:'#d9dde2'})+`<rect x="${n(vx-4)}" y="-12" width="5" height="2.4" rx="1" fill="${b?'#3a6fde':'#1b2a5c'}"/>`+(k>2?person(vx-22,{f:-1,jersey:'#2a3a6a',hat:false})+bubble(vx-22,-21,'Bonsoir…'):''),light:`<circle cx="${n(vx-2)}" cy="-11" r="${b?10:6}" fill="#3a6fde" opacity=".25"/>`+(k>2?`<path d="M${n(vx-20)} -8 L-6 -2 L-6 10Z" fill="#fff4c4" opacity=".2"/>`:'')};});
add('soirg','L’arceau cassé','« Crac ! » un arceau casse et la tente s’affaisse d’un côté. Il hausse les épaules.',5,k=>{const p=seg(k,1.6,2.2);return {sky:'dusk',body:tent(4,{p:1-p*.45,lean:-p*6})+parked(-34)+person(26,{f:-1,pose:k>2.6?'shrug':'stand'})+(k>1.6&&k<2.8?word(4,-10,'crac !',1,4.4):'')};});
add('soirg','Le déluge','Une pluie diluvienne, l’eau monte autour de la tente qui tremble.',5,k=>{const h=seg(k,0,4)*4;return {sky:'night',pre:clouds('#1c2433'),body:tent(0,{glow:1,shake:1})+parked(-34)+`<rect x="-80" y="${n(11-h)}" width="160" height="${n(h+1)}" fill="#4f8fb8" opacity=".7"/>`,over:rain(80)};});
add('soirg','La nuit glacée','Le givre recouvre la tente, petits nuages de buée, le thermomètre descend sous zéro.',5,k=>{const f=seg(k,0,3.5);return {sky:'night',body:tent(4,{glow:.6,frost:f})+parked(-32)+[0,1].map(i=>{const p=(T*.6+i*.5)%1;return `<circle cx="${n(4+p*6)}" cy="${n(4-p*8)}" r="${n(1+p*2)}" fill="#e8f4ff" opacity="${n(.6*(1-p))}"/>`;}).join('')+Array.from({length:8},(_,i)=>`<path transform="translate(${-40+i*11} ${-30+(i*7)%14})" d="M-1.4 0 h2.8 M0 -1.4 v2.8" stroke="#e8f4ff" stroke-width=".4" opacity="${n(f*(.5+.5*Math.sin(T*3+i)))}"/>`).join(''),over:`<g transform="translate(26 30)"><rect x="-3" y="0" width="6" height="34" rx="3" fill="#f6e7c1" stroke="#1b3b38"/><rect x="-1.4" y="${n(10+f*18)}" width="2.8" height="${n(24-f*18)}" fill="#3a6fde"/><text x="8" y="30" font-size="12" font-weight="900" fill="#cfe3f1" font-family="Barlow">-2°</text></g>`};});
add('soirg','La mauvaise bouteille de gaz','Accroupi devant le réchaud : « clic, clic »… quelques étincelles, pas de flamme.',4,k=>{const c=Math.floor(T*2.5)%2;return {sky:'dusk',body:tent(26)+person(-6,{pose:'crouch',f:1,hat:false})+`<rect x="0" y="7" width="5" height="4" rx="1" fill="#3a6fb0"/><rect x="-.6" y="5.6" width="6.2" height="1.4" fill="#26343c"/>`+(c?`<circle cx="2.5" cy="4.4" r="1" fill="#ffe08a"/>`:'')+word(2,-8,c?'clic':'clic',c?1:.4,3.4)+(k>3?word(-6,-20,'…',1,6):'')};});
add('soirg','Camping complet','Il arrive au camping : un tampon « COMPLET » s’abat sur le panneau. Il repart.',5,k=>{const p=seg(k,1.4,1.8),x=k<1.4?mv(k,0,1.4,-60,-6):k<3?-6:mv(k,3,5,-6,70);return {sky:'dusk',body:`<rect x="-46" y="-12" width="18" height="23" fill="#c9a36b" stroke="#1b1406" stroke-width=".6"/><path d="M-48 -12 L-37 -19 L-26 -12Z" fill="#8f3b26"/>`+sign(-37,'CAMPING')+(k>1.4?`<g transform="translate(-37 -15.5) rotate(-12) scale(${n(3-p*2)})" opacity="${n(p)}"><rect x="-10" y="-3" width="20" height="6" fill="none" stroke="#e0574a" stroke-width="1"/><text y="1.6" text-anchor="middle" font-size="4" font-weight="900" fill="#e0574a" font-family="Barlow">COMPLET</text></g>`:'')+riding(x)+(k>1.8&&k<3?bubble(x+4,-21,'zut…'):'')};});
add('soirg','Les voisins bruyants','La tente d’à côté fait la fête : notes de musique, lumières qui clignotent ; sa tente à lui bougonne.',4,k=>{const c=['#e0574a','#f2a541','#6f9a3a','#3a6fde'][Math.floor(T*4)%4];return {sky:'night',body:tent(-22,{glow:.6})+tent(24,{col:'#7a4a8a',glow:1})+[0,1,2].map(i=>{const p=(T*.7+i/3)%1;return `<text x="${n(24+Math.sin(p*8+i)*6)}" y="${n(-2-p*20)}" font-size="5" fill="#ffe08a" opacity="${n(1-p)}">♪</text>`;}).join('')+word(-22,-6,'grrr',1,3.6),light:`<circle cx="24" cy="2" r="16" fill="${c}" opacity=".18"/>`};});
add('soirg','Les punaises','Dans le lit, des petites bêtes courent sur la couverture ; il se gratte partout.',4,k=>{return {sky:'day',mtn:false,pre:`<rect x="-48" width="416" height="150" fill="#4a3c30"/><rect x="40" y="20" width="60" height="44" fill="#1c2a4a" stroke="#c9a36b" stroke-width="3"/><circle cx="80" cy="34" r="6" fill="#f6ecc8"/>`,body:`<rect x="-34" y="0" width="60" height="9" rx="2" fill="#f6f6ee" stroke="#1b1406" stroke-width=".5"/><rect x="-34" y="9" width="2" height="4" fill="#5b4228"/><rect x="24" y="9" width="2" height="4" fill="#5b4228"/><rect x="-34" y="-6" width="3" height="15" fill="#7a5a34"/>`+person(-4,{pose:'swat',hat:false,y:-2})+Array.from({length:7},(_,i)=>`<ellipse cx="${n(-28+((T*6+i*9)%52))}" cy="${n(2+Math.sin(T*5+i)*1.6)}" rx=".9" ry=".6" fill="#6a2a1a"/>`).join('')+word(-4,-22,'gratte gratte',1,3.4)};});
add('soirg','Le repas qui passe mal','Le ventre qui gargouille : il sort de la tente en courant vers les buissons… et recommence.',5,k=>{const p=(k%2.5)/2.5,x=p<.5?mv(p,0,.5,8,40):mv(p,.5,1,40,8);return {sky:'night',body:tent(4,{glow:1})+`<ellipse cx="46" cy="7" rx="10" ry="6" fill="#26402c"/>`+person(x,{pose:'belly',f:p<.5?1:-1,hat:false})+`<path transform="translate(${n(x)} -21) rotate(${n(T*200)})" d="M0 0 m-2 0 a2 2 0 1 1 4 0 a1 1 0 1 1 -2 0" stroke="#7fbf5a" stroke-width=".6" fill="none"/>`};});
add('soirg','Le téléphone oublié','Au camping, il cherche sa poche… le téléphone est resté sur la table du café, il vibre tout seul là-bas.',5,k=>{const v=Math.sin(T*40)*.4;return {sky:'dusk',body:`<rect x="-56" y="-2" width="16" height="1.4" fill="#7a5a34"/><rect x="-48.8" y="-.6" width="1.4" height="11.6" fill="#5b4228"/><rect x="${n(-51+v)}" y="-4.4" width="3" height="2.4" rx=".5" fill="#26343c"/><circle cx="-49.5" cy="-6" r="${n(2+Math.abs(Math.sin(T*3))*2)}" fill="none" stroke="#7fc0e8" stroke-width=".4"/>`+tent(28)+person(10,{pose:k>1.8?'arms':'stand',f:-1})+`<path d="M-44 -6 Q-20 -24 6 -16" stroke="#f6e7c1" stroke-width=".5" stroke-dasharray="1.6 1.6" fill="none" opacity="${n(seg(k,2,2.6))}"/>`+(k>1.8?word(10,-22,'!',1,8,'#ffe08a'):'')};});
// 4 · Belles soirées
add('soirb','La nuit étoilée','Allongé près de la tente, il regarde le ciel : une étoile filante le traverse.',5,k=>{const p=seg(k,1.4,2.4);return {sky:'night',body:tent(26,{glow:.5})+parked(-40)+person(-12,{pose:'lie'}),over:p>0&&p<1?`<path d="M${n(40+p*180)} ${n(10+p*40)} l-26 -6" stroke="#fffbe8" stroke-width="1.6" stroke-linecap="round" opacity="${n(1-p*.6)}"/><circle cx="${n(40+p*180)}" cy="${n(10+p*40)}" r="2" fill="#fff"/>`:''};});
add('soirb','Les bières de l’inconnu','Un voyageur sort deux bières de son van : ils trinquent, « tchin ! ».',4,k=>{const t=Math.floor(T*.8)%2;return {sky:'dusk',body:van(34,{dir:-1})+parked(-40)+person(-14,{pose:'toast',f:1,hat:false})+person(8,{pose:'toast',f:-1,jersey:'#3a6fb0',hat:false})+(t?word(-3,-22,'tchin !',1,4):'')};});
add('soirb','La meute protectrice','Trois chiens du coin se couchent autour de la tente et veillent, la queue qui bat.',5,k=>{return {sky:'night',body:tent(0,{glow:.8})+dog(-24,{lie:true})+dog(22,{lie:true,dir:-1,col:'#c9a36b'})+dog(-6,{lie:true,col:'#3a2a1c'}),light:hearts(0,-16)};});
add('soirb','Le feu de bois','Un vrai feu de camp, des étincelles qui montent, deux voyageurs assis autour.',4,k=>{return {sky:'night',body:tent(36,{glow:.4})+person(-16,{pose:'sit',f:1,hat:false})+person(16,{pose:'sit',f:-1,jersey:'#3a6fb0',hat:false}),light:fire(0,1.6)+[0,1,2,3].map(i=>{const p=(T*.7+i/4)%1;return `<circle cx="${n(Math.sin(p*7+i)*4)}" cy="${n(2-p*28)}" r=".6" fill="#ffd27a" opacity="${n(1-p)}"/>`;}).join('')};});
add('soirb','Les voyageurs au long cours','Trois tentes en cercle, on se raconte les voyages : une carte, un globe, un drapeau passent dans les bulles.',5,k=>{const ic=['🗺️','🌍','⛰️','🚲'][Math.floor(T*.8)%4];return {sky:'dusk',body:tent(-38,{col:'#5d86b8',w:8})+tent(40,{col:'#6f9a63',w:8})+person(-14,{pose:'sit',f:1,hat:false})+person(14,{pose:'sit',f:-1,jersey:'#6b4a8a',hat:false})+person(0,{pose:'sit',f:1,jersey:'#3a6fb0',hat:false,y:-1})+`<g transform="translate(0 -24)"><rect x="-6" y="-5" width="12" height="9" rx="3" fill="#fffaf0" stroke="#1b1406" stroke-width=".4"/><text y="2" text-anchor="middle" font-size="6">${ic}</text></g>`};});
add('soirb','Le camping qui ferme','Fin de saison : le patron retourne le panneau « FERMÉ »… et lui fait signe de rester, gratuit.',5,k=>{const flip=seg(k,1.2,1.8);return {sky:'dusk',body:`<rect x="-46" y="-12" width="18" height="23" fill="#c9a36b" stroke="#1b1406" stroke-width=".6"/><path d="M-48 -12 L-37 -19 L-26 -12Z" fill="#8f3b26"/><g transform="translate(-37 -15) scale(${n(Math.abs(1-flip*2))} 1)"><rect x="-10" y="-4" width="20" height="7" rx="1.2" fill="${flip<.5?'#e0574a':'#6f9a3a'}"/><text y="1.4" text-anchor="middle" font-size="3.6" font-weight="900" fill="#fff" font-family="Barlow">${flip<.5?'FERMÉ':'ENTRE !'}</text></g>`+person(-20,{f:1,jersey:'#6b4a8a',hat:false,pose:k>2?'wave':'stand'})+parked(10)+person(24,{f:-1})+(k>2.2?bubble(-20,-21,'reste, c’est gratuit')+hearts(24,-16):'')};});
add('soirb','Le jour de lessive','Une corde à linge entre l’arbre et le vélo, les maillots flottent au vent du soir.',4,k=>{const cl=(x,c,i)=>`<path transform="translate(${x} -15) skewX(${n(Math.sin(T*3+i)*10)})" d="M-3 0 h6 v6 h-1.4 v-3 h-3.2 v3 h-1.4Z" fill="${c}"/>`;return {sky:'dusk',body:tree(-40)+parked(36,0)+`<path d="M-38 -16 Q0 -12 40 -16" stroke="#f6f6ee" stroke-width=".4" fill="none"/>`+cl(-24,'#b8432e',0)+cl(-12,'#3a6fb0',1)+cl(0,'#f2a541',2)+cl(12,'#6f9a3a',3)+person(-2,{pose:'stand',hat:false})};});
add('soirb','Le festival','Guirlandes lumineuses, feux d’artifice qui éclatent, il danse avec les gens du coin.',4,k=>{const bursts=[[80,30,0],[230,24,.7],[160,40,1.4]].map(([x,y,d])=>{const p=((T*.6+d)%2)/2;if(p>.6)return '';const r=p*45,c=['#f2a541','#e0574a','#7fc0e8'][Math.round(d*2)%3];return `<g transform="translate(${x} ${y})" opacity="${n(1-p/.6)}">${Array.from({length:10},(_,i)=>`<circle cx="${n(Math.cos(i*.628)*r)}" cy="${n(Math.sin(i*.628)*r)}" r="1.6" fill="${c}"/>`).join('')}</g>`;}).join('');
 return {sky:'night',over:bursts,body:`<path d="M-66 -24 Q0 -14 66 -24" stroke="#26343c" stroke-width=".3" fill="none"/>`+person(-20,{pose:'dance',hat:false})+person(0,{pose:'dance',jersey:'#6b4a8a',hat:false})+person(20,{pose:'dance',jersey:'#3a6fb0',hat:false}),light:Array.from({length:11},(_,i)=>`<circle cx="${-60+i*12}" cy="${n(-23+Math.sin(i/10*Math.PI)*5)}" r="1.2" fill="${['#f2a541','#e0574a','#6f9a3a','#7fc0e8'][(i+Math.floor(T*3))%4]}"/>`).join('')};});
add('soirb','Le concert d’accordéon','Un musicien du village joue de l’accordéon (le soufflet s’ouvre et se ferme), il danse.',4,k=>{const o=(Math.sin(T*4)+1)/2;return {sky:'dusk',body:person(-14,{f:1,jersey:'#7a4a2c',hat:false,pose:'stand'})+`<g transform="translate(-9 -7)"><rect x="-2" y="-3" width="2" height="6" fill="#b8432e"/><rect x="${n(.2+o*3)}" y="-3" width="2" height="6" fill="#b8432e"/>${Array.from({length:4},(_,i)=>`<path d="M${n(i*(o*3+.4)/4)} -3 v6" stroke="#1b1406" stroke-width=".3"/>`).join('')}<rect x="0" y="-3" width="${n(o*3+.4)}" height="6" fill="#f6e7c1" opacity=".6"/></g>`+person(16,{pose:'dance'})+[0,1,2].map(i=>{const p=(T*.6+i/3)%1;return `<text x="${n(-6+p*14+Math.sin(p*9)*3)}" y="${n(-12-p*18)}" font-size="5" fill="#ffe08a" opacity="${n(1-p)}">♪</text>`;}).join('')};});


add('sit','Les vendanges','Les rangs de vigne, il cueille les grappes dans un panier, une pièce brille.',5,k=>{const vine=x=>`<path d="M${x} 11 V-4" stroke="#5b4228" stroke-width="1"/><circle cx="${x}" cy="-6" r="5" fill="#4b7a35"/>${[0,1].map(i=>`<circle cx="${x-2+i*4}" cy="${-2+i}" r="1.6" fill="#6b3a8a"/>`).join('')}`;
 return {sky:'hot',body:[-50,-34,22,38,54].map(vine).join('')+person(-12,{pose:k%2<1?'crouch':'stand',f:1,hat:false})+`<path d="M-4 6 h7 l-1 5 h-5Z" fill="#c9a36b" stroke="#1b1406" stroke-width=".4"/>${[0,1,2].map(i=>`<circle cx="${-2.4+i*2}" cy="5.6" r="1.1" fill="#6b3a8a"/>`).join('')}`+(k>2.6?`<g transform="translate(0 ${n(-14-seg(k,2.6,3.6)*6)})" opacity="${n(1-seg(k,3.4,4))}"><circle r="3" fill="#f2c14e" stroke="#8a5a14" stroke-width=".5"/></g>`:'')};});
add('sit','La fête nationale','Des fanions partout, des feux d’artifice, on danse sur la place du village.',4,k=>{const bursts=[[80,30,0],[230,24,.7]].map(([x,y,d])=>{const p=((T*.6+d)%2)/2;if(p>.6)return '';const r=p*45;return `<g transform="translate(${x} ${y})" opacity="${n(1-p/.6)}">${Array.from({length:10},(_,i)=>`<circle cx="${n(Math.cos(i*.628)*r)}" cy="${n(Math.sin(i*.628)*r)}" r="1.6" fill="${['#3a6fde','#f6f6ee','#e0574a'][i%3]}"/>`).join('')}</g>`;}).join('');
 return {sky:'night',over:bursts,body:`<path d="M-66 -24 Q0 -14 66 -24" stroke="#26343c" stroke-width=".3" fill="none"/>`+Array.from({length:12},(_,i)=>`<path d="M${-60+i*11} ${n(-23+Math.sin(i/11*Math.PI)*5)} l2 4 l2 -4Z" fill="${['#3a6fde','#f6f6ee','#e0574a'][i%3]}"/>`).join('')+person(-14,{pose:'dance',hat:false})+person(6,{pose:'dance',jersey:'#3a6fb0',hat:false})+person(24,{pose:'dance',jersey:'#e0574a',hat:false})};});

// Scènes sans dessin à elles (imprévus, compagnons, rencontres du mode original) : une scène simple selon le moment.
const GENERIC={
 route:{P:4,fn:k=>({road:1,body:riding(mv(k,0,4,-60,30))})},
 imprevu:{P:4,fn:k=>{const x=mv(k,0,1.6,-60,-4);return {road:1,body:riding(x)+(k>1.6?word(x+2,-24,'!',1,8,'#ffe08a'):'')};}},
 soir:{P:4,fn:k=>({sky:'dusk',body:tent(14,{p:seg(k,.6,1.8)})+parked(-30)+person(-8,{pose:'stand'})})},
 rencontre:{P:4,fn:k=>({road:1,body:riding(mv(k,0,2,-60,-14))+person(16,{f:-1,jersey:'#3a6fb0',hat:false,pose:k>2?'wave':'stand'})+(k>2.2?hearts(16,-16):'')})}};

// ---------- Mode original : les 40 cartes Événement (validées par Fi le 17 octobre : mêmes animations que les rencontres) ----------
add('carte','Vent dans le dos','Le vent pousse dans le dos, il file sans pédaler.',4,k=>({road:1,body:riding(mv(k,0,4,-70,70),{lean:-1}),over:`<g transform="scale(-1 1) translate(-320 0)">${wind()}</g>`}));
add('carte','Belle descente','Une longue descente, il file les cheveux au vent.',4,k=>{const x=mv(k,0,4,-70,70);return {road:1,body:riding(x,{rot:12,y:-6+seg(k,0,4)*10})+[0,1,2].map(i=>`<path d="M${n(x-14-i*3)} ${-4+i*4} h-7" stroke="#f6f6ee" stroke-width=".6"/>`).join('')};});
add('carte','Raccourci découvert','Un petit chemin caché : une flèche s’allume et il coupe à travers.',4.5,k=>{const x=mv(k,1.2,4.5,-50,60);return {road:1,body:`<path d="M-30 6 Q0 -10 40 4" stroke="#d9c89c" stroke-width="3" fill="none" stroke-dasharray="3 2" opacity="${n(seg(k,.2,1))}"/>`+word(0,-14,'➜',seg(k,.4,1),7,'#ffe08a')+riding(x,{y:x>-30&&x<40?-Math.sin((x+30)/70*Math.PI)*6:0})};});
add('carte','Coup de pouce','Un bouclier lumineux arrête le coup dur.',4,k=>{const p=seg(k,.6,1.6);return {road:1,body:riding(-10)+`<g transform="translate(14 -6) scale(${n(p)})"><path d="M0 -12 L9 -8 L8 2 Q6 9 0 12 Q-6 9 -8 2 L-9 -8Z" fill="#7fc0e8" stroke="#f6e7c1" stroke-width="1"/><path d="M-3 0 l2.4 2.6 l4.6 -5.6" stroke="#fff" stroke-width="1.4" fill="none"/></g>`+(k>1.6?word(14,-22,'paré !',1,4):'')};});
add('carte','Sacoche déchirée','La sacoche craque, les affaires tombent sur la route.',4.5,k=>{const x=mv(k,0,1.8,-60,-4),p=seg(k,1.8,3);return {road:1,body:riding(x)+(k>1.8?[0,1,2,3].map(i=>`<rect x="${n(x-12-i*3-p*i*4)}" y="${n(-2+p*(10+i))}" width="3" height="2.4" fill="${['#f2a541','#3a6fb0','#e0574a','#6f9a3a'][i]}" transform="rotate(${n(p*90*i)} ${n(x-12)} 4)"/>`).join('')+word(x-12,-6,'crac !',1-seg(k,3,4),4):'')};});
add('carte','Brouillard épais','Un brouillard laiteux avale la route, on ne voit plus qu’une silhouette.',5,k=>({road:1,body:riding(mv(k,0,5,-50,40)),over:[0,1,2].map(i=>`<ellipse cx="${n(((T*14+i*120)%440)-60)}" cy="${80+i*22}" rx="120" ry="22" fill="#eef2f2" opacity=".55"/>`).join('')+`<rect x="-48" width="416" height="150" fill="#e6ecec" opacity=".35"/>`}));
add('carte','Neige au sommet','Les flocons tombent, la route blanchit, il pousse son vélo dans la neige.',5,k=>({sky:'storm',road:1,body:`<rect x="-80" y="9" width="160" height="${n(1+seg(k,0,4)*3)}" fill="#f6f6ff"/>`+parked(mv(k,0,5,-40,10),0)+person(mv(k,0,5,-26,24),{pose:'walk'}),over:`<g fill="#fff">`+Array.from({length:40},(_,i)=>`<circle cx="${n((i*37.7+Math.sin(T+i)*8)%440-58)}" cy="${n((T*40+i*53)%170-10)}" r="1.4"/>`).join('')+`</g>`}));
add('carte','Équipement','Nouveau matériel : il brille sur le vélo, petites étincelles.',4,k=>({road:1,body:parked(-6,0)+person(14,{f:-1,pose:'arms'})+[0,1,2,3,4].map(i=>{const p=(T*.7+i/5)%1;return `<path transform="translate(${n(-10+i*6)} ${n(-10-p*8)}) scale(${n(Math.sin(p*Math.PI))})" d="M0 -2 L.6 -.6 L2 0 L.6 .6 L0 2 L-.6 .6 L-2 0 L-.6 -.6Z" fill="#ffe08a"/>`;}).join('')}));
add('carte','Petit boulot','Un coup de main à la ferme : il porte des caisses, une pièce brille.',4.5,k=>({body:`<rect x="-46" y="-6" width="16" height="17" fill="#d9c4a0" stroke="#1b1406" stroke-width=".5"/><path d="M-48 -6 L-38 -13 L-28 -6Z" fill="#8f3b26"/>`+person(mv(k,0,2.4,-20,10),{pose:'walk'})+`<rect x="${n(mv(k,0,2.4,-17,13))}" y="-12" width="6" height="5" fill="#c9a36b" stroke="#1b1406" stroke-width=".4"/>`+(k>2.6?`<g transform="translate(10 ${n(-20-seg(k,2.6,3.6)*6)})"><circle r="3" fill="#f2c14e" stroke="#8a5a14" stroke-width=".5"/></g>`:'')}));
const CARD_SCENE={'evt-01':'Vent dans le dos','evt-02':'L’addition','evt-03':'Belle descente','evt-05':'Petit boulot','evt-06':'Le marché','evt-07':'Coup de pouce','evt-08':'Paysage exceptionnel','evt-09':'Raccourci découvert','evt-10':'« On t’avance ? »',
 'evt-11':'Pschhh…','evt-12':'Le rayon qui casse','evt-13':'Vent de face','evt-14':'L’orage sur le col','evt-15':'La mauvaise bifurcation','evt-16':'La chute à l’arrêt','evt-17':'Le repas qui passe mal','evt-18':'Route barrée','evt-19':'Sacoche déchirée','evt-20':'Le dérailleur capricieux',
 'evt-21':'Vent de face','evt-22':'39 °C sans ombre','evt-23':'L’orage sur le col','evt-24':'Brouillard épais','evt-25':'Neige au sommet','evt-26':'La drache','evt-27':'Vent de face','evt-28':'La nuit glacée','evt-29':'La drache','evt-30':'La nuit glacée'};
// Scène d'une carte Événement (« Nuit chez l'habitant » se joue avec la scène de la nuit, voir app.js).
export function cardScene(id,category){return BY_TITLE[CARD_SCENE[id]]||(category==='permanent'?BY_TITLE['Équipement']:GENERIC.rencontre);}

// Moment où l'image s'arrête (l'animation se joue une fois puis reste vivante sur cette image).
export function sceneFor(title,kind='route'){return BY_TITLE[title]||GENERIC[kind]||GENERIC.route;}
export function sceneHold(sc){return sc.P*.78;}
export function encounterSceneSvg(sc,elapsed,{href='',x,y,color='#b8432e',uid='enc',now=performance.now()}={}){T=now/1000;C=color||'#b8432e';
 const k=Math.min(Math.max(0,elapsed),sceneHold(sc));let r;try{r=sc.fn(k);}catch{r={body:''};}return frame(uid,r,{href,x,y});}
